// 1. Data Hazard Resolution: Forwarding/Bypassing

#define WRITEBACK_STAGE 4
#define EXECUTE_STAGE 2

typedef struct { int src_reg; int dest_reg; } Instruction;
int ALU_Output_Latched = 0; // Value ready early

// Logic to check if data can be forwarded from EXE stage
int resolve_data_dependency(Instruction current, int needed_reg) {
    // Current instruction needs a result that is still in flight (EXE stage)
    if (current.src_reg == needed_reg &&
        current.pipeline_stage < WRITEBACK_STAGE) {
        return ALU_Output_Latched; // Bypass memory/register file
    }
    return -1; // Wait for normal Writeback
}


// 2. Control Hazard Resolution: Branch Prediction and Flushing (Squashing)

enum BranchState { PREDICTED_TAKEN, PREDICTED_NOT_TAKEN };
#define NOP 0x00000000 // A No Operation instruction

BranchState prediction = PREDICTED_NOT_TAKEN;
bool outcome_is_taken = false;

// Squashing instructions on misprediction
void flush_pipeline(int fetch_depth) {
    if ((prediction == PREDICTED_TAKEN) != outcome_is_taken) {
        // Misprediction detected. Flush subsequent stages
        for (int i = 0; i < fetch_depth; i++) {
            pipeline_register[i] = NOP;
        }
    }
}


// 3. Data Hazard Resolution: Stalling (Load-Use Hazard)

#define DECODE 1
#define EXECUTE 2

typedef struct { int op; int rd; int rs; } PipelineReg;
PipelineReg ID_IR, EX_IR; // Instruction Registers

// Check for necessary stall (e.g., LOAD instruction followed immediately by USE)
bool check_load_use_stall() {
    if (EX_IR.op == LOAD &&
        (ID_IR.rs == EX_IR.rd || ID_IR.rt == EX_IR.rd)) {
        return true; // Stall (Insert Bubble in DECODE stage)
    }
    return false;
}

// How the bubble is inserted
void advance_pipeline() {
    if (check_load_use_stall()) {
        ID_IR.op = NOP; // DECODE stage holds NOP
    } else {
        EX_IR = ID_IR;
    }
}
